import sys

def solve(inp):
    tokens = inp.strip().split()
    if not tokens: return ''
    n = int(tokens[0])
    c = 0
    res = [' ' * (n - 1) + chr(65 + c)]
    c += 1
    for i in range(1, n - 1):
        res.append(' ' * (n - 1 - i) + chr(65 + c) + ' ' * (2 * i) + chr(65 + c + 1))
        c += 2
    bottom = ''.join(chr(65 + c + j) for j in range(2 * n))
    res.append(bottom)
    return '\n'.join(res)


def main():
    s = sys.stdin.read()
    if s.strip():
        print(solve(s))

if __name__ == '__main__':
    main()

code.JavaScript:
const fs = require('fs');
function solve(inp) {
    const tokens = inp.trim().split(/\s+/);
    if (!tokens || tokens.length === 0 || tokens[0] === '') return '';
    const n = parseInt(tokens[0], 10);
    let c = 0;
    const res = [' '.repeat(n - 1) + String.fromCharCode(65 + c)];
    c += 1;
    for (let i = 1; i < n - 1; i++) {
        res.push(' '.repeat(n - 1 - i) + String.fromCharCode(65 + c) + ' '.repeat(2 * i) + String.fromCharCode(65 + c + 1));
        c += 2;
    }
    let bottom = '';
    for (let j = 0; j < 2 * n; j++) bottom += String.fromCharCode(65 + c + j);
    res.push(bottom);
    return res.join('\n');
}
function main() {
    const s = fs.readFileSync(0, 'utf-8').trim();
    if (s.length > 0) console.log(solve(s));
}
main();

